import{_ as o,C as r,o as i,c as n,a6 as e,E as l}from"./chunks/framework.Bd7kzaCy.js";const s="/xi-kari-skill/handbook/images/prediction.svg",b=JSON.parse('{"title":"能预测常态，为什么未必能预测改变后的结果","description":"常态下相同的状态，面对干预可能响应不同。","frontmatter":{"title":"能预测常态，为什么未必能预测改变后的结果","description":"常态下相同的状态，面对干预可能响应不同。"},"headers":[],"relativePath":"concepts/prediction.md","filePath":"concepts/prediction.md"}'),c={name:"concepts/prediction.md"};function p(d,a,h,_,u,m){const t=r("PredictionExplorer");return i(),n("div",null,[a[0]||(a[0]=e('<h1 id="能预测常态-为什么未必能预测改变后的结果" tabindex="-1">能预测常态，为什么未必能预测改变后的结果 <a class="header-anchor" href="#能预测常态-为什么未必能预测改变后的结果" aria-label="Permalink to &quot;能预测常态，为什么未必能预测改变后的结果&quot;">​</a></h1><p>合并后的模型平时很准，采取同一措施时为什么会失灵？</p><p><strong>常态下相同的状态，面对干预可能响应不同。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文设想两种微观状态A₁和A₂。在自然演化中，它们进入B的概率都为0.2，所以只针对这项预测，把两者合成一个A可能已经足够。加入某项干预后，A₁进入B的概率变成0.8，A₂则为0.1。此时同样一个宏观A，若内部两类比例不同，干预后的结果就不同：A₁的份额为p时，进入B的概率为0.1＋0.7p。</p><p>原文给出的修正方向是只补入与这个问题相关的份额p，而不是先恢复所有微观细节。但补入p能帮助这项判断，也不自动证明模型掌握了p本身将怎样更新，更不证明适用于任何新操作。理解这个例子，要一直把表示与具体任务、期限和允许操作放在一起看。</p><figure class="concept-figure"><img src="'+s+'" alt="同样的常态概率，不同的干预响应"><figcaption>所有数值均来自原文教学设定；p表示A₁在A中的份额。</figcaption></figure><h2 id="改变条件-看看有什么不同" tabindex="-1">改变条件，看看有什么不同 <a class="header-anchor" href="#改变条件-看看有什么不同" aria-label="Permalink to &quot;改变条件，看看有什么不同&quot;">​</a></h2>',8)),l(t),a[1]||(a[1]=e('<h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>常态预测充分不保证新增干预下仍充分</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-6">§4.6 G4 表示闭合与对象或干预转换</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这些概率是原文教学构造，不是现实系统测量。模型内形式结论不自动取得现实经验支持；常态预测、干预响应、长期闭合和规范可用性分别成立。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./representation.html">平均数准确，为什么仍看不见局部过载</a></li><li><a href="./chain.html">两段都有效，整条链为什么仍可能无效</a></li></ul>',7))])}const k=o(c,[["render",p]]);export{b as __pageData,k as default};
